                                  'CentOS',
                                  'CoreOS',
                                  'Debian',
                                  'Fedora',
                                  'Fedora Atomic',
                                  'FreeBSD',
                                  'Gentoo',
                                  'openSUSE',
                                  'RancherOS',
                                  'Rocky Linux',
                                  'Ubuntu',
                                  'Unknown',
